package com.fream.back.domain.m16.repository;

import com.fream.back.domain.m16.dto.Xzj27ResponseDto;
import com.fream.back.domain.m16.dto.Xwf85Dto;
import com.fream.back.domain.m16.entity.Xtz73Status;
import com.fream.back.domain.m16.entity.QXdg64;
import com.fream.back.domain.m16.entity.QXzj27;
import com.fream.back.domain.m02.entity.QXkr46;
import com.fream.back.domain.m02.entity.QXfp92;
import com.fream.back.domain.m02.entity.QXzq99;
import com.fream.back.domain.m02.entity.QXdh20;
import com.fream.back.domain.m12.entity.QXhx14;
import com.fream.back.domain.m13.entity.QXrd81;
import com.querydsl.core.BooleanBuilder;
import com.querydsl.core.Tuple;
import com.querydsl.core.types.Projections;
import com.querydsl.jpa.impl.JPAQueryFactory;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageImpl;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Repository;
import org.springframework.util.StringUtils;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;




@Repository
@RequiredArgsConstructor
public class Xzj27RepositoryImpl implements Xzj27RepositoryCustom {
    private final JPAQueryFactory queryFactory;

    @Override
    public Page<Xzj27ResponseDto> findOrderBidsByFilters(String email, String bidStatus, String orderStatus, Pageable pageable) {
        QXzj27 orderBid = QXzj27.xzj27;
        QXdg64 order = QXdg64.xdg64;
        QXdh20 productSize = QXdh20.xdh20;
        QXfp92 productColor = QXfp92.xfp92;
        QXkr46 product = QXkr46.xkr46;
        QXzq99 productImage = QXzq99.xzq99;
        QXhx14 orderShipment = QXhx14.xhx14;
        QXrd81 user = QXrd81.xrd81;


        BooleanBuilder whereBuilder = new BooleanBuilder();


        if (StringUtils.hasText(email)) {
            whereBuilder.and(user.email.eq(email));
        }


        if (StringUtils.hasText(bidStatus)) {
            whereBuilder.and(orderBid.status.stringValue().eq(bidStatus));
        }


        if (StringUtils.hasText(orderStatus)) {
            whereBuilder.and(order.status.stringValue().eq(orderStatus));
        }


        List<Xzj27ResponseDto> content = queryFactory
                .select(Projections.constructor(
                        Xzj27ResponseDto.class,
                        orderBid.id,
                        product.id,
                        product.name,
                        product.englishName,
                        productSize.size,
                        productColor.colorName,
                        productImage.imageUrl,
                        orderBid.bidPrice,
                        orderBid.status.stringValue(),
                        order.status.stringValue(),
                        orderShipment.status.stringValue(),
                        orderBid.createdDate,
                        orderBid.modifiedDate
                ))
                .from(orderBid)
                .join(orderBid.user, user)
                .join(orderBid.productSize, productSize)
                .join(productSize.productColor, productColor)
                .join(productColor.product, product)
                .join(productColor.thumbnailImage, productImage)
                .leftJoin(orderBid.order, order)
                .leftJoin(order.orderShipment, orderShipment)
                .where(whereBuilder)
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();


        Long total = queryFactory
                .select(orderBid.id.count())
                .from(orderBid)
                .join(orderBid.user, user)
                .leftJoin(orderBid.order, order)
                .where(whereBuilder)
                .fetchOne();

        return new PageImpl<>(content, pageable, total != null ? total : 0L);
    }

    @Override
    public Xwf85Dto countOrderBidsByStatus(String email) {
        QXzj27 orderBid = QXzj27.xzj27;


        Long pendingCount = queryFactory
                .select(orderBid.count())
                .from(orderBid)
                .where(orderBid.status.eq(Xtz73Status.PENDING)
                        .and(orderBid.user.email.eq(email)))
                .fetchOne();


        Long matchedCount = queryFactory
                .select(orderBid.count())
                .from(orderBid)
                .where(orderBid.status.eq(Xtz73Status.MATCHED)
                        .and(orderBid.user.email.eq(email)))
                .fetchOne();


        Long cancelledOrCompletedCount = queryFactory
                .select(orderBid.count())
                .from(orderBid)
                .where(orderBid.status.in(
                                Xtz73Status.CANCELLED, Xtz73Status.COMPLETED)
                        .and(orderBid.user.email.eq(email)))
                .fetchOne();


        pendingCount = pendingCount != null ? pendingCount : 0L;
        matchedCount = matchedCount != null ? matchedCount : 0L;
        cancelledOrCompletedCount = cancelledOrCompletedCount != null ? cancelledOrCompletedCount : 0L;

        return new Xwf85Dto(pendingCount, matchedCount, cancelledOrCompletedCount);
    }

    @Override
    public Xzj27ResponseDto findOrderBidById(Long orderBidId, String email) {
        QXzj27 orderBid = QXzj27.xzj27;
        QXdg64 order = QXdg64.xdg64;
        QXdh20 productSize = QXdh20.xdh20;
        QXfp92 productColor = QXfp92.xfp92;
        QXkr46 product = QXkr46.xkr46;
        QXzq99 productImage = QXzq99.xzq99;
        QXhx14 orderShipment = QXhx14.xhx14;
        QXrd81 user = QXrd81.xrd81;

        return queryFactory
                .select(Projections.constructor(
                        Xzj27ResponseDto.class,
                        orderBid.id,
                        product.id,
                        product.name,
                        product.englishName,
                        productSize.size,
